import * as React from "react"
import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

// Monochrome Industrial Button: monochrome, industrial, sharp corners.
// Default = white-on-black (or black-on-white in light mode), no shadows,
// 1px hairline border separation, Space Mono ALL CAPS for the label.
// Destructive uses the signal-light red.

const buttonVariants = cva(
  [
    "relative inline-flex items-center justify-center gap-2 whitespace-nowrap",
    "font-[family-name:var(--font-mono)] uppercase tracking-[0.08em] text-[0.75rem] font-medium",
    "rounded-none border transition-[background-color,color,border-color] duration-fast ease-out",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--mono-accent)] focus-visible:ring-offset-0",
    "disabled:pointer-events-none disabled:opacity-40",
    "active:translate-y-[0.0625rem]",
  ].join(" "),
  {
    variants: {
      variant: {
        // Primary: high-contrast slab. Inverted background, no shadow.
        default:
          "bg-primary text-primary-foreground border-primary " +
          "hover:bg-primary/90 hover:border-primary/90",
        // Secondary: surface with hairline border.
        secondary:
          "bg-[var(--mono-surface-raised)] text-foreground border-[var(--mono-border-visible)] " +
          "hover:border-foreground/60",
        // Outline: fully transparent, border carries the weight.
        outline:
          "bg-transparent text-foreground border-[var(--mono-border-visible)] " +
          "hover:border-foreground hover:bg-[var(--mono-surface)]",
        // Ghost: no border, no fill, label only. The minimal end of the system.
        ghost:
          "bg-transparent text-muted-foreground border-transparent " +
          "hover:text-foreground hover:bg-[var(--mono-surface)]",
        // Destructive: the signal-light red moment.
        destructive:
          "bg-[var(--mono-accent)] text-white border-[var(--mono-accent)] " +
          "hover:bg-[var(--mono-accent)]/90",
        // Link: Space Mono underlined.
        link:
          "border-transparent text-foreground underline underline-offset-[0.375rem] decoration-[0.0625rem] " +
          "hover:text-[var(--mono-accent)]",
      },
      size: {
        sm:      "h-8  px-3 text-[0.6875rem]",
        default: "h-10 px-5",
        lg:      "h-12 px-7 text-[0.8125rem]",
        icon:    "h-10 w-10",
        "icon-sm": "h-8 w-8",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

export interface ButtonProps
  extends Omit<ButtonPrimitive.Props, "className">,
    VariantProps<typeof buttonVariants> {
  className?: string
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    // Callers written against the Radix API pass the element to become as a
    // child: <Button asChild><Link>…</Link></Button>. Base UI has no asChild,
    // it composes through `render`. Without this the prop reaches the DOM and
    // the anchor nests inside the button instead of replacing it, which stacks
    // the icon above the label and puts a link inside a button.
    if (asChild && React.isValidElement(props.children)) {
      const { children, ...rest } = props
      return (
        <ButtonPrimitive
          ref={ref}
          className={cn(buttonVariants({ variant, size, className }))}
          {...rest}
          // After the spread, so an explicit asChild child wins over a stray
          // render prop rather than being silently replaced by it.
          // SAFETY: this branch runs only when `asChild` is set, and the caller then
          // owns passing a single element for the slot to clone.
          render={children as React.ReactElement}
        />
      )
    }

    return (
      <ButtonPrimitive
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        {...props}
      />
    )
  }
)
Button.displayName = "Button"

export { Button, buttonVariants }
